type Subscription={plan:SubscriptionPlan;periodMonth:string;monthlyUsed:number;extraCredits:number;trialEnds?:string;trialUsed?:boolean;selectedPlan?:SubscriptionPlan};
const planCredits:Record<SubscriptionPlan,number>={free:0,essential:10,plus:30,premium:80};
const planNames:Record<SubscriptionPlan,string>={free:'Gratuito',essential:'Essencial',plus:'Plus',premium:'Premium'};
const planRank:Record<SubscriptionPlan,number>={free:0,essential:1,plus:2,premium:3};
